/* LearnForge - Corporate Website Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
  --radius: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-900);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

a {
  text-decoration: none;
  color: inherit;
}

img {
  max-width: 100%;
  height: auto;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--black);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); font-weight: 800; }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.5rem, 3vw, 2rem); }
h4 { font-size: 1.25rem; }

p { color: var(--gray-600); }

.text-center { text-align: center; }
.text-lime { color: var(--lime); }
.text-burgundy { color: var(--burgundy); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 14px 28px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  gap: 8px;
}

.btn-primary {
  background: var(--black);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--gray-800);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-secondary {
  background: transparent;
  color: var(--black);
  border: 2px solid var(--black);
}

.btn-secondary:hover {
  background: var(--black);
  color: var(--white);
}

.btn-lime {
  background: var(--lime);
  color: var(--black);
}

.btn-lime:hover {
  background: #d4eb2d;
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-larger {
  padding: 18px 36px;
  font-size: 1.125rem;
}

/* Navigation */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--gray-100);
  z-index: 1000;
  padding: 16px 0;
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--black);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-logo svg {
  width: 32px;
  height: 32px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-link {
  font-weight: 500;
  color: var(--gray-600);
  transition: var(--transition);
  position: relative;
}

.nav-link:hover, .nav-link.active {
  color: var(--black);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--lime);
  transition: var(--transition);
}

.nav-link:hover::after, .nav-link.active::after {
  width: 100%;
}

.nav-cta {
  margin-left: 16px;
}

/* Hero Section */
.hero {
  padding: 160px 0 80px;
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
  min-height: 90vh;
  display: flex;
  align-items: center;
}

.hero-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.hero h1 {
  margin-bottom: 24px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-600);
  margin-bottom: 40px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 48px;
}

/* Tab Switch */
.tab-switch {
  display: flex;
  background: var(--gray-100);
  border-radius: var(--radius);
  padding: 6px;
  margin-bottom: 32px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

.tab-btn {
  flex: 1;
  padding: 12px 24px;
  border: none;
  background: transparent;
  font-weight: 600;
  color: var(--gray-500);
  border-radius: 8px;
  cursor: pointer;
  transition: var(--transition);
}

.tab-btn.active {
  background: var(--white);
  color: var(--black);
  box-shadow: var(--shadow-md);
}

.tab-content {
  display: none;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: 24px;
  margin-top: 24px;
}

.tab-content.active {
  display: block;
  animation: fadeIn 0.4s ease;
}

.tab-preview {
  background: var(--gray-50);
  border-radius: var(--radius);
  padding: 20px;
  min-height: 200px;
}

.preview-header {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

.preview-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--gray-300);
}

.preview-dot:nth-child(1) { background: #FF5F57; }
.preview-dot:nth-child(2) { background: #FFBD2E; }
.preview-dot:nth-child(3) { background: #28CA42; }

.preview-nav {
  display: flex;
  gap: 16px;
  padding: 12px;
  background: var(--white);
  border-radius: 8px;
  margin-bottom: 16px;
}

.preview-nav-item {
  padding: 8px 16px;
  background: var(--gray-100);
  border-radius: 6px;
  font-size: 0.875rem;
  color: var(--gray-600);
}

.preview-content {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.preview-card {
  background: var(--white);
  padding: 16px;
  border-radius: 8px;
  box-shadow: var(--shadow-sm);
}

.preview-card-icon {
  width: 40px;
  height: 40px;
  background: var(--lime);
  border-radius: 8px;
  margin-bottom: 8px;
}

.preview-card-title {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--black);
}

/* Stats Bar */
.stats-bar {
  background: var(--black);
  padding: 60px 0;
  color: var(--white);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px;
  text-align: center;
}

.stat-item h3 {
  font-size: clamp(2.5rem, 4vw, 3.5rem);
  color: var(--lime);
  margin-bottom: 8px;
}

.stat-item p {
  color: var(--gray-400);
  font-size: 1.125rem;
}

/* Sections */
.section {
  padding: 100px 0;
}

.section-dark {
  background: var(--gray-900);
  color: var(--white);
}

.section-dark h2, .section-dark h3, .section-dark h4 {
  color: var(--white);
}

.section-gray {
  background: var(--gray-50);
}

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 64px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  font-size: 1.125rem;
}

/* Products Grid */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  transition: var(--transition);
  border: 1px solid var(--gray-100);
}

.product-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-xl);
  border-color: var(--lime);
}

.product-icon {
  width: 64px;
  height: 64px;
  background: var(--lime);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.product-icon svg {
  width: 32px;
  height: 32px;
  color: var(--black);
}

.product-card h4 {
  margin-bottom: 12px;
}

.product-card p {
  font-size: 0.9375rem;
}

/* Why Choose Us Tabs */
.why-tabs {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 48px;
}

.why-tab {
  padding: 14px 28px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius);
  background: var(--white);
  font-weight: 600;
  color: var(--gray-600);
  cursor: pointer;
  transition: var(--transition);
}

.why-tab:hover {
  border-color: var(--gray-400);
  color: var(--black);
}

.why-tab.active {
  background: var(--black);
  border-color: var(--black);
  color: var(--white);
}

.why-content {
  display: none;
}

.why-content.active {
  display: block;
  animation: fadeIn 0.4s ease;
}

.why-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.why-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 28px;
  box-shadow: var(--shadow-md);
  border-left: 4px solid var(--lime);
}

.why-card h4 {
  margin-bottom: 8px;
}

/* Features Grid */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.feature-card {
  text-align: center;
  padding: 32px;
}

.feature-icon {
  width: 80px;
  height: 80px;
  background: var(--lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
}

.feature-icon svg {
  width: 40px;
  height: 40px;
  color: var(--black);
}

.feature-card h4 {
  margin-bottom: 12px;
}

/* Integrations Grid */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 24px;
  align-items: center;
}

.integration-item {
  background: var(--white);
  padding: 24px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
  height: 80px;
}

.integration-item:hover {
  transform: scale(1.05);
  box-shadow: var(--shadow-md);
}

.integration-item svg {
  width: 40px;
  height: 40px;
  color: var(--gray-600);
}

/* Testimonials Carousel */
.testimonials-wrapper {
  position: relative;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  flex: 0 0 calc(33.333% - 16px);
  margin-right: 24px;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
}

.testimonial-card:last-child {
  margin-right: 0;
}

.testimonial-header {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 16px;
}

.testimonial-avatar {
  width: 56px;
  height: 56px;
  background: var(--lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--black);
}

.testimonial-info h4 {
  margin-bottom: 4px;
}

.testimonial-info p {
  font-size: 0.875rem;
  color: var(--gray-500);
}

.testimonial-tag {
  display: inline-block;
  background: var(--lime);
  color: var(--black);
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  margin-bottom: 12px;
}

.testimonial-card blockquote {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--gray-700);
  font-style: italic;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--gray-200);
  background: var(--white);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}

.carousel-btn:hover {
  background: var(--black);
  border-color: var(--black);
  color: var(--white);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
}

/* Pricing Overview */
.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px 32px;
  box-shadow: var(--shadow-md);
  text-align: center;
  position: relative;
  border: 2px solid transparent;
  transition: var(--transition);
}

.pricing-card:hover {
  border-color: var(--lime);
  transform: translateY(-4px);
}

.pricing-card.featured {
  border-color: var(--lime);
  transform: scale(1.02);
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--lime);
  color: var(--black);
  padding: 4px 16px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
}

.pricing-card h4 {
  margin-bottom: 8px;
}

.pricing-card .price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--black);
  margin-bottom: 8px;
}

.pricing-card .price span {
  font-size: 1rem;
  font-weight: 400;
  color: var(--gray-500);
}

.pricing-card .desc {
  color: var(--gray-500);
  margin-bottom: 24px;
}

.pricing-features {
  text-align: left;
  margin-bottom: 32px;
}

.pricing-features li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  color: var(--gray-700);
  font-size: 0.9375rem;
}

.pricing-features li svg {
  width: 20px;
  height: 20px;
  color: var(--lime);
  flex-shrink: 0;
}

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  background: var(--white);
  border-radius: var(--radius);
  margin-bottom: 16px;
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  border: 1px solid var(--gray-100);
}

.faq-question {
  width: 100%;
  padding: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font-weight: 600;
  font-size: 1.0625rem;
  color: var(--black);
  transition: var(--transition);
}

.faq-question:hover {
  background: var(--gray-50);
}

.faq-icon {
  width: 24px;
  height: 24px;
  transition: transform 0.3s ease;
  flex-shrink: 0;
}

.faq-item.active .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-answer-content {
  padding: 0 24px 24px;
  color: var(--gray-600);
  line-height: 1.7;
}

.faq-item.active .faq-answer {
  max-height: 500px;
}

/* CTA Banner */
.cta-banner {
  background: var(--black);
  padding: 80px 0;
  text-align: center;
}

.cta-banner h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.cta-banner p {
  color: var(--gray-400);
  font-size: 1.125rem;
  margin-bottom: 32px;
}

/* Footer */
.footer {
  background: var(--gray-900);
  color: var(--white);
  padding: 80px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand h3 {
  color: var(--white);
  font-size: 1.5rem;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.footer-brand p {
  color: var(--gray-400);
  margin-bottom: 24px;
}

.footer-links h4 {
  color: var(--white);
  margin-bottom: 20px;
  font-size: 1rem;
}

.footer-links ul {
  list-style: none;
}

.footer-links li {
  margin-bottom: 12px;
}

.footer-links a {
  color: var(--gray-400);
  transition: var(--transition);
}

.footer-links a:hover {
  color: var(--lime);
}

.footer-bottom {
  border-top: 1px solid var(--gray-800);
  padding-top: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--gray-500);
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: 24px;
}

.footer-legal a {
  color: var(--gray-500);
  transition: var(--transition);
}

.footer-legal a:hover {
  color: var(--white);
}

/* Steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px;
}

.step-card {
  text-align: center;
  position: relative;
}

.step-number {
  width: 64px;
  height: 64px;
  background: var(--lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--black);
  margin: 0 auto 24px;
}

.step-card h4 {
  margin-bottom: 12px;
}

/* Spotlight */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.spotlight-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  text-align: center;
}

.spotlight-card h4 {
  margin-bottom: 8px;
}

.spotlight-card p {
  color: var(--gray-500);
}

/* Value Props */
.value-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.value-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  border-top: 4px solid var(--lime);
}

.value-card h4 {
  margin-bottom: 12px;
}

/* File Types */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 24px;
}

.file-type-item {
  background: var(--gray-100);
  padding: 24px 16px;
  border-radius: var(--radius);
  text-align: center;
  transition: var(--transition);
}

.file-type-item:hover {
  background: var(--lime);
  transform: translateY(-4px);
}

.file-type-item svg {
  width: 32px;
  height: 32px;
  color: var(--gray-600);
  margin-bottom: 8px;
}

.file-type-item span {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-700);
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-in {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.fade-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* Responsive */
@media (max-width: 1024px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .integrations-grid { grid-template-columns: repeat(4, 1fr); }
  .testimonial-card { flex: 0 0 calc(50% - 12px); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-cta { display: none; }
  .stats-grid { grid-template-columns: 1fr; gap: 32px; }
  .features-grid { grid-template-columns: 1fr; }
  .pricing-cards { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; }
  .why-grid { grid-template-columns: 1fr; }
