  margin-bottom: 48px;
}

.footer-brand h3 {
  color: var(--white);
  font-size: 1.5rem;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.footer-brand p {
  color: var(--gray-400);
  margin-bottom: 24px;
}

.footer-links h4 {
  color: var(--white);
  margin-bottom: 20px;
  font-size: 1rem;
}

.footer-links ul {
  list-style: none;
}

.footer-links li {
  margin-bottom: 12px;
}

.footer-links a {
  color: var(--gray-400);
  transition: var(--transition);
}

.footer-links a:hover {
  color: var(--lime);
}

.footer-bottom {
  border-top: 1px solid var(--gray-800);
  padding-top: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--gray-500);
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: 24px;
}

.footer-legal a {
  color: var(--gray-500);
  transition: var(--transition);
}

.footer-legal a:hover {
  color: var(--white);
}

/* Steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px;
}

.step-card {
  text-align: center;
  position: relative;
}

.step-number {
  width: 64px;
  height: 64px;
  background: var(--lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--black);
  margin: 0 auto 24px;
}

.step-card h4 {
  margin-bottom: 12px;
}

/* Spotlight */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.spotlight-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  text-align: center;
}

.spotlight-card h4 {
  margin-bottom: 8px;
}

.spotlight-card p {
  color: var(--gray-500);
}

/* Value Props */
.value-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.value-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  border-top: 4px solid var(--lime);
}

.value-card h4 {
  margin-bottom: 12px;
}

/* File Types */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 24px;
}

.file-type-item {
  background: var(--gray-100);
  padding: 24px 16px;
  border-radius: var(--radius);
  text-align: center;
  transition: var(--transition);
}

.file-type-item:hover {
  background: var(--lime);
  transform: translateY(-4px);
}

.file-type-item svg {
  width: 32px;
  height: 32px;
  color: var(--gray-600);
  margin-bottom: 8px;
}

.file-type-item span {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-700);
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-in {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.fade-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* Responsive */
@media (max-width: 1024px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .integrations-grid { grid-template-columns: repeat(4, 1fr); }
  .testimonial-card { flex: 0 0 calc(50% - 12px); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-cta { display: none; }
  .stats-grid { grid-template-columns: 1fr; gap: 32px; }
  .features-grid { grid-template-columns: 1fr; }
  .pricing-cards { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; }
  .why-grid { grid-template-columns: 1fr; }
  .file-types-grid { grid-template-columns: repeat(3, 1fr); }
  .spotlight-grid { grid-template-columns: 1fr; }
  .value-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
  .testimonial-card { flex: 0 0 100%; }
  .preview-content { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: repeat(3, 1fr); }
}

/* Resources Grid */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.resource-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  transition: var(--transition);
  border: 1px solid var(--gray-100);
}

.resource-card:hover {
  transform: translateY(-4px);
  border-color: var(--lime);
  box-shadow: var(--shadow-lg);
}

.resource-card h4 {
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.resource-card h4 svg {
  width: 24px;
  height: 24px;
  color: var(--lime);
}

/* Tools Grid */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.tool-category {
  background: var(--white);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.tool-category h4 {
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--lime);
  font-size: 1rem;
}

.tool-category ul {
  list-style: none;
}

.tool-category li {
  padding: 8px 0;
  color: var(--gray-600);
  font-size: 0.9375rem;
  display: flex;
  align-items: center;
  gap: 8px;
}

.tool-category li::before {
  content: '';
  width: 6px;
  height: 6px;
  background: var(--lime);
  border-radius: 50%;
}

/* Membership Stats */
.membership-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-bottom: 64px;
}

.membership-stat {
  text-align: center;
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
}

.membership-stat h3 {
  font-size: 2.5rem;
  color: var(--lime);
  margin-bottom: 8px;
}

/* Engagement Features */
.engagement-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.engagement-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-md);
  text-align: center;
}

.engagement-icon {
  width: 80px;
  height: 80px;
  background: var(--gray-100);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
}

.engagement-icon svg {
  width: 40px;
  height: 40px;
  color: var(--black);
}

.engagement-card h4 {
  margin-bottom: 12px;
}

/* Demo Accordion */
.demo-accordion {
  max-width: 800px;
  margin: 0 auto;
}

.demo-item {
  background: var(--white);
  border-radius: var(--radius);
  margin-bottom: 16px;
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.demo-header {
  width: 100%;
  padding: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  font-weight: 600;
  font-size: 1.0625rem;
  color: var(--black);
}

.demo-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.demo-content-inner {
  padding: 0 24px 24px;
}

.demo-item.active .demo-content {
  max-height: 600px;
}

.demo-item.active .faq-icon {
  transform: rotate(180deg);
}
